f.arrow([(310, 80), (310, 268)], "lnr", "ar"); f.text(318, 180, "it is held:", "s red"); f.text(318, 194, "mark the word", "s red"); f.text(318, 208, "\"someone waits\",", "s red"); f.text(318, 222, "then wait(word, value)", "s red")
